def langname(code): return {'he':'עברית','ru':'Русский','en':'English'}[code]
def qas(code,title):
    if code=='he': return [(f'מתי כדאי לפנות לעורך דין בנושא {title}?','כאשר נדרש לקבל החלטה, לחתום על מסמך, להגיב להליך או להבין את הזכויות והחובות לפני ביצוע פעולה.'),(f'מה כדאי להכין לפגישה בנושא {title}?','מסמכים רלוונטיים, התכתבויות, מועדים חשובים ותיאור כרונולוגי קצר של העניין מסייעים לבחינה ראשונית יעילה.')]
    if code=='ru': return [(f'Когда стоит обратиться к адвокату по вопросу «{title}»?','До подписания документов, ответа на официальное требование или совершения действия, которое может повлиять на ваши права и обязанности.'),(f'Что подготовить к первой встрече по вопросу «{title}»?','Полезно собрать относящиеся к делу документы, переписку, важные даты и краткую хронологию событий.')]
    return [(f'When should I seek legal advice about {title}?','Before signing documents, responding to a formal process, or taking a step that may affect your rights or obligations.'),(f'What should I prepare for an initial meeting about {title}?','Relevant documents, correspondence, key dates and a short chronology of events can make the initial review more effective.')]

def schema_local(code,url,title,desc,faq):
    local={'@context':'https://schema.org','@type':'LegalService','name':langs[code]['firm'],'url':url,'telephone':'+972-50-269-2223','email':'office@lawtmo.com','address':{'@type':'PostalAddress','streetAddress':'גולדנהירש 30','addressLocality':'פתח תקווה','addressCountry':'IL'},'areaServed':{'@type':'Country','name':'Israel'},'serviceType':title,'description':desc}
    faqsch={'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in faq]}
    bread={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':langs[code]['nav'][1],'item':f'https://www.lawtmo.com/{code}/practice/'},{'@type':'ListItem','position':2,'name':title,'item':url}]}
    return ''.join(f'<script type="application/ld+json">{json.dumps(x,ensure_ascii=False)}</script>' for x in [local,faqsch,bread])

def page(code,s):
    L=langs[code]; title,desc,items=s[code]; faq=qas(code,title); url=f'https://www.lawtmo.com/{code}/practice/{s["slug"]}/'
    alts=''.join(f'<link rel="alternate" hreflang="{c}" href="https://www.lawtmo.com/{c}/practice/{s["slug"]}/">' for c in ['he','ru','en'])+f'<link rel="alternate" hreflang="x-default" href="https://www.lawtmo.com/he/practice/{s["slug"]}/">'
    langswitch=''.join(f'<a href="../../../{c}/practice/{s["slug"]}/"'+(' aria-current="page"' if c==code else '')+f'>{langname(c)}</a>' for c in ['he','ru','en'])
    itemhtml=''.join(f'<li>{escape(x)}</li>' for x in items)
    faqhtml=''.join(f'<details class="faq-item"><summary>{escape(q)}</summary><p>{escape(a)}</p></details>' for q,a in faq)
    return f'''<!doctype html><html lang="{code}" dir="{L['dir']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | {escape(L['firm'])}</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{url}">{alts}<meta property="og:type" content="website"><meta property="og:title" content="{escape(title)} | {escape(L['firm'])}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{url}"><link rel="stylesheet" href="../../../assets/styles.css">{schema_local(code,url,title,desc,faq)}</head><body dir="{L['dir']}"><a class="skip-link" href="#main">Skip</a><header><div class="container nav"><a class="brand" href="../../"><span class="brand-mark">TM</span><span class="brand-copy"><strong>{escape(L['firm'])}</strong><span>{escape(L['office'])}</span></span></a><nav class="nav-links" aria-label="Main"><a href="../../about/">{L['nav'][0]}</a><a href="../">{L['nav'][1]}</a><a href="../../articles/">{L['nav'][2]}</a><a href="../../contact/">{L['nav'][3]}</a><a class="nav-cta" href="../../contact/">{L['contact']}</a></nav><div class="lang">{langswitch}</div><button class="menu-btn" aria-expanded="false" aria-label="Menu">☰</button></div></header><main id="main"><section class="page-hero dark"><div class="container page-hero-grid"><div><div class="eyebrow">{L['nav'][1]}</div><h1>{escape(title)}</h1><p>{escape(desc)}</p><div class="page-actions"><a class="btn btn-primary" href="../../contact/">{L['cta']}</a><a class="text-link" href="../">← {L['back']}</a></div></div><div class="page-monogram" aria-hidden="true">TM</div></div></section><section class="section"><div class="container service-layout"><aside class="service-aside"><div class="eyebrow">{L['services']}</div><h2>{escape(title)}</h2><p>{escape(L['note'])}</p></aside><div class="service-body"><ul class="service-list">{itemhtml}</ul><section class="faq-block"><div class="eyebrow">FAQ</div><h2>{L['faq']}</h2>{faqhtml}</section><div class="service-cta"><div><strong>{escape(L['firm'])}</strong><p>{escape(L['address'])}</p></div><div class="hero-actions"><a class="btn btn-primary" data-track="whatsapp_cta" href="https://wa.me/972502692223">WhatsApp</a><a class="btn btn-outline-dark" data-track="phone_cta" href="tel:+972502692223">050-2692223</a></div></div></div></div></section></main><footer><div class="container footer-grid"><div class="footer-brand"><div class="brand"><span class="brand-mark">TM</span><span class="brand-copy"><strong>{escape(L['firm'])}</strong><span>{escape(L['office'])}</span></span></div><p>{escape(L['address'])}</p></div><div class="footer-col"><h4>Legal</h4><a href="../../privacy/">Privacy</a><a href="../../accessibility/">Accessibility</a></div><div class="footer-col"><h4>{L['contact']}</h4><a href="tel:+972502692223">+972 50-269-2223</a><a href="mailto:office@lawtmo.com">office@lawtmo.com</a></div></div><div class="container footer-bottom"><span>© 2026 {escape(L['firm'])}</span></div></footer><a class="floating-wa" data-track="whatsapp_cta" href="https://wa.me/972502692223" aria-label="WhatsApp">WA</a><script src="../../../assets/config.js" defer></script><script src="../../../assets/site.js" defer></script></body></html>'''

for s in services:
    for code in langs:
        p=ROOT/code/'practice'/s['slug']/'index.html'; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(page(code,s),encoding='utf-8')

# replace practice grids on index pages with linked cards
for code in langs:
    p=ROOT/code/'practice'/'index.html'; txt=p.read_text(encoding='utf-8')
    cards=''.join(f'<a class="detail-card practice-link" href="./{s["slug"]}/"><span class="detail-dot">◆</span><h3>{escape(s[code][0])}</h3><p>{escape(s[code][1])}</p></a>' for s in services)
    txt=re.sub(r'<div class="detail-grid">.*?</div></div></div></section>',f'<div class="detail-grid">{cards}</div></div></div></section>',txt,count=1,flags=re.S)
    p.write_text(txt,encoding='utf-8')

# make homepage practice cards link to relevant detail pages where names are known
home_map={
'he':{'מקרקעין':'real-estate','התחדשות עירונית':'urban-renewal','חדלות פירעון':'insolvency','הוצאה לפועל':'enforcement'},
'ru':{'Недвижимость':'real-estate','Городское обновление':'urban-renewal','Несостоятельность':'insolvency','Исполнительное производство':'enforcement'},
'en':{'Real estate':'real-estate','Urban renewal':'urban-renewal','Insolvency':'insolvency','Enforcement proceedings':'enforcement'}}
for code,m in home_map.items():
    p=ROOT/code/'index.html'; txt=p.read_text(encoding='utf-8')
    for label,slug in m.items():
        pattern=rf'<article class="practice">(.*?<h3>{re.escape(label)}</h3>.*?</article>)'
        txt=re.sub(pattern,rf'<a class="practice" href="./practice/{slug}/">\1</a>',txt,flags=re.S)
    p.write_text(txt,encoding='utf-8')

