addon='''\n.practice-link{display:block;color:inherit}.practice-link p{color:var(--muted);font-size:.88rem;margin:.65rem 0 0}.service-layout{display:grid;grid-template-columns:.72fr 1.28fr;gap:80px}.service-aside{position:sticky;top:120px;align-self:start}.service-aside h2,.faq-block h2{font-family:Georgia,serif;font-size:clamp(2rem,4vw,3.5rem);font-weight:500;line-height:1.08;margin:14px 0 18px}.service-aside p{color:var(--muted)}.service-list{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:1fr 1fr;gap:12px}.service-list li{background:var(--white);border:1px solid rgba(16,17,17,.08);border-radius:16px;padding:18px 20px;position:relative;padding-inline-start:42px}.service-list li:before{content:"◆";position:absolute;inset-inline-start:18px;color:var(--gold);font-size:.62rem;top:23px}.faq-block{margin-top:60px}.faq-item{border-top:1px solid #d9d0c1;padding:18px 0}.faq-item:last-child{border-bottom:1px solid #d9d0c1}.faq-item summary{cursor:pointer;font-weight:800}.faq-item p{color:var(--muted);max-width:760px}.service-cta{margin-top:55px;background:var(--ink);color:var(--white);border-radius:var(--radius);padding:28px 32px;display:flex;align-items:center;justify-content:space-between;gap:30px}.service-cta p{margin:4px 0 0;color:#aaa59a}.service-cta .btn-outline-dark{border-color:rgba(255,255,255,.3);color:white}@media(max-width:850px){.service-layout{grid-template-columns:1fr;gap:34px}.service-aside{position:static}.service-list{grid-template-columns:1fr}}@media(max-width:600px){.service-cta{align-items:flex-start;flex-direction:column;padding:24px}}\n'''
if '.service-layout{' not in text: css.write_text(text+addon,encoding='utf-8')

# sitemap append practice pages before closing
sp=ROOT/'sitemap.xml'; st=sp.read_text(encoding='utf-8'); entries=[]
for code in langs:
    for s in services: entries.append(f'<url><loc>https://www.lawtmo.com/{code}/practice/{s["slug"]}/</loc></url>')
st=re.sub(r'</urlset>\s*$', '\n'.join(entries)+'\n</urlset>', st)
sp.write_text(st,encoding='utf-8')
